% Loan amortisation schedule (MATLAB or GNU Octave)
P = 200000; r = 0.06/12; n = 25*12;
payment = P*r / (1 - (1 + r)^(-n));

balance = zeros(1, n+1);
balance(1) = P;                 % arrays start at index 1
for k = 1:n
    balance(k+1) = balance(k)*(1 + r) - payment;
end

fprintf('Monthly payment: GBP %.2f\n', payment);
fprintf('Balance after 10 years: GBP %.0f\n', balance(121));
plot(0:n, balance); xlabel('Month'); ylabel('Balance (GBP)');
